import { PlaneGeometry, Mesh, Group, DirectionalLight, Color, Vector3 } from 'three/webgpu';
import { MeshStandardNodeMaterial, uniform, texture, uv, position, mul, add, vec3, float } from 'three/tsl';
import { gsap } from 'gsap';
import { parallaxScroll, depthRotate } from '@/primitives';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Load textures ---
  const imageTexturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthTexturePromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

  // --- Create geometry ---
  const geometry = new PlaneGeometry(2, 1.25, 64, 64);

  // --- Create material with TSL displacement ---
  const material = new MeshStandardNodeMaterial({
    color: 0xffffff,
    metalness: 0.3,
    roughness: 0.6,
    clearcoat: 0.1,
    side: 2, // DoubleSide
  });

  // Set map and displacementMap via promises
  let imageTexture, depthTexture;
  Promise.all([imageTexturePromise, depthTexturePromise]).then(([imgTex, depthTex]) => {
    imageTexture = imgTex;
    depthTexture = depthTex;
    material.map = imgTex;
    material.needsUpdate = true;

    // TSL displacement node
    const depthTexNode = texture(depthTex, uv());
    const scale = uniform(0.05); // displacement scale
    const displacement = mul(depthTexNode, scale);
    const displacedPosition = add(position, mul(displacement, vec3(0, 0, 1))); // displace along normal (Z)
    material.positionNode = displacedPosition;
    material.needsUpdate = true;
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // --- Add rim light ---
  const rimLight = new DirectionalLight(new Color(config.colors?.accent || '#ff2a38'), 0.8);
  rimLight.position.set(0, 0, 2); // behind the plane
  group.add(rimLight);

  // --- Add a subtle key light from front-left ---
  const keyLight = new DirectionalLight(0xffffff, 0.3);
  keyLight.position.set(1, 0.5, 1);
  group.add(keyLight);

  // --- Weighted-settle entrance ---
  const entranceTimeline = gsap.timeline();
  group.scale.set(1.04, 1.04, 1.04);
  entranceTimeline.to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  // --- Hover effect: rise-in ---
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power2.out',
  });

  // --- Click handler ---
  group.userData.handlers = {
    pointerenter: () => {
      hoverTimeline.play();
    },
    pointerleave: () => {
      hoverTimeline.reverse();
    },
    click: () => {
      ctx.emit('hub-home.select', {});
    },
  };

  // --- Apply cinematic primitives ---
  const primitiveCleanups = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      const result = ctx.primitives[prim.name](group, prim.params);
      if (result && result.cleanup) {
        primitiveCleanups.push(result.cleanup);
      }
    }
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    entranceTimeline.kill();
    hoverTimeline.kill();
    geometry.dispose();
    material.dispose();
    if (imageTexture) imageTexture.dispose();
    if (depthTexture) depthTexture.dispose();
    primitiveCleanups.forEach(fn => fn());
  };

  return group;
}
